SELECT id, c2 FROM rows1 WHERE - 'RbkZYkNZQ0dq1d' IS NOT c3 NOT IN (SELECT t918.id - rows1.c2 FROM rows1 AS t918 WHERE t918.c4 AND t918.id = rows1.c1 AND t918.c1 = rows1.c1) ORDER BY c1 ASC NULLS LAST, c3 DESC LIMIT 953;
